# Законы Литвы (DE_TOPICS), LAW_TAGS, параметры. Реакции партий: own=ЛСДП, cons=TS-LKD, popr=«Заря Немана», soc=Демократы «Во имя Литвы»,
# popl=крестьяне и зелёные (ЛВЖС), lib=Либеральное движение, oth=прочие и независимые, euro=Партия свободы, region=Акция поляков Литвы, prot=Национальное объединение.
from lt_lib import *
from ie_lib import V as _V

TOPICS = []


def V(n, d, c=None, s=None, a=None, ps=None, st=None, rg=None, set=None, tag=None, x=None):
    """вариант закона; x — множители (edu_eff, health_eff, env_eff, admin_mult ...)"""
    v = _V(n, d, c=c, s=s, a=a, ps=ps, st=st, rg=rg, set=set, tag=tag)
    if x: v["x"] = x
    return v


def add(*a, **k):
    TOPICS.append(T(*a, **k))


